"export type TraderStatus = 'FOLLOWING' | 'FIRED' | 'BENCH';

export interface Trader {
  id: string;
  handle: string;
  name: string;
  initials: string;
  avatarColor: string;
  rank: number;
  weeklyRank: string;
  sevenDayReturn: number; // e.g. 412 for +412%
  winRate: number; // e.g. 66 for 66%
  copyRatio: number; // e.g. 0.25 for 0.25x
  status: TraderStatus;
  pnlWithUs: number; // P&L earned with our bot
  lastSix: ('W' | 'L')[];
}

export type LogType = 'COPY' | 'EXIT' | 'FIRE' | 'SCAN' | 'PICK' | 'SYSTEM' | 'QUANT';

export interface TradeLog {
  id: string;
  timestamp: string;
  type: LogType;
  traderHandle?: string;
  token?: string;
  action?: 'bought' | 'sold' | 'fired' | 'picked' | 'scanned';
  amountUsd?: number;
  pnlUsd?: number;
  pnlPercent?: number;
  copyRatio?: string;
  message: string;
  isLoss?: boolean;
}

export interface ChartPoint {
  timeIndex: number;
